242	\toprule
243	\textbf{Embedding} & \textbf{Control} & \textbf{Raw $\rho$} & \textbf{Raw $p$} & \textbf{Partial $r$} & \textbf{Partial $p$} \\
244	\midrule
245	MiniLM & --- & $+$0.208 & $0.011$ & --- & --- \\
246	MiniLM & log freq & --- & --- & $+$0.133 & $0.11$ \\
247	MiniLM & log freq $+$ degree & --- & --- & --- & $0.23$ \\
248	\midrule
